class Solution {
    fun maximumRobots(chargeTimes:IntArray,runningCosts:IntArray,budget:Long):Int{
        val deque=java.util.ArrayDeque<Int>();
        var running=0L;
        var left=0;
        var answer=0;
        for(right in chargeTimes.indices){
            running+=runningCosts[right];
            while(deque.isNotEmpty()&&chargeTimes[deque.peekLast()]<=chargeTimes[right])deque.removeLast();
            deque.addLast(right);
            while(left<=right&&chargeTimes[deque.peekFirst()].toLong()+(right-left+1)*running>budget){
                if(deque.peekFirst()==left)deque.removeFirst();
                running-=runningCosts[left++]
            };
            answer=maxOf(answer,right-left+1)
        };
        return answer
    }
}

